import collections

def get_min_boxes(n):
    initial_state = tuple(sorted([1] * n))
    visited = {initial_state: 0}
    queue = collections.deque([initial_state])
    min_boxes = n

    while queue:
        state = queue.popleft()
        min_boxes = min(min_boxes, len(state))
        if min_boxes == 1:
            return 1

        # Try all possible moves
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                m1 = state[i]
                m2 = state[j]
                for k in range(1, min(m1, m2) + 1):
                    # New state
                    new_elements = []
                    if m1 - k > 0:
                        new_elements.append(m1 - k)
                    if m2 - k > 0:
                        new_elements.append(m2 - k)
                    new_elements.append(2 * k)

                    # The other elements
                    for idx in range(len(state)):
                        if idx != i and idx != j:
                            new_elements.append(state[idx])

                    new_state = tuple(sorted([x for x in new_elements if x > 0]))
                    if new_state not in visited:
                        visited[new_state] = visited[state] + 1
                        queue.append(new_state)

    return min_boxes

for n in range(1, 11):
    print(f"n={n}, min_boxes={get_min_boxes(n)}")

